    // math (national)
    ['commission-total', 'math', 'national', 0, 'Licensing exam content outline · Real estate calculations: commissions',
        ['A home sells for $280,000 at a 6% commission. What is the total commission?', ['$16,800', '$18,600', '$1,680', '$168,000'], '$280,000 × 0.06 = $16,800.'],
        ['Una casa se vende en $280,000 con una comisión del 6%. ¿Cuál es la comisión total?', ['$16,800', '$18,600', '$1,680', '$168,000'], '$280,000 × 0.06 = $16,800.']],
    ['commission-agent-share', 'math', 'national', 2, 'Licensing exam content outline · Real estate calculations: commissions',
        ['A $300,000 sale pays 6%, split 50/50 between brokerages. The agent gets 70% of the brokerage\'s share. How much does the agent earn?', ['$9,000', '$12,600', '$6,300', '$18,000'], '$300,000 × 6% = $18,000; half is $9,000; 70% of $9,000 = $6,300.'],
        ['Una venta de $300,000 paga 6%, dividido 50/50 entre las agencias. El agente recibe el 70% de la parte de su agencia. ¿Cuánto gana el agente?', ['$9,000', '$12,600', '$6,300', '$18,000'], '$300,000 × 6% = $18,000; la mitad es $9,000; el 70% de $9,000 = $6,300.']],
    ['commission-rate', 'math', 'national', 1, 'Licensing exam content outline · Real estate calculations: commissions',
        ['A broker earned $12,750 on a $255,000 sale. What was the commission rate?', ['4.5%', '5%', '5.5%', '6%'], 'Rate = commission ÷ price: $12,750 ÷ $255,000 = 0.05, or 5%.'],
        ['Un bróker ganó $12,750 en una venta de $255,000. ¿Cuál fue la tasa de comisión?', ['4.5%', '5%', '5.5%', '6%'], 'Tasa = comisión ÷ precio: $12,750 ÷ $255,000 = 0.05, o 5%.']],
    ['price-from-net', 'math', 'national', 3, 'Licensing exam content outline · Real estate calculations: seller net',
        ['A seller wants to net $190,000 after a 5% commission. What is the lowest price that works (rounded)?', ['$199,500', '$195,000', '$190,950', '$200,000'], 'Price = net ÷ (1 − 0.05) = $190,000 ÷ 0.95 = $200,000.'],
        ['Un vendedor quiere recibir neto $190,000 después de una comisión del 5%. ¿Cuál es el precio mínimo que funciona (redondeado)?', ['$199,500', '$195,000', '$190,950', '$200,000'], 'Precio = neto ÷ (1 − 0.05) = $190,000 ÷ 0.95 = $200,000.']],
    ['sqft-rectangle', 'math', 'national', 0, 'Licensing exam content outline · Real estate calculations: area',
        ['A room measures 14 feet by 16 feet. How many square feet is it?', ['224', '60', '30', '196'], 'Area = length × width = 14 × 16 = 224 square feet.'],
        ['Una habitación mide 14 por 16 pies. ¿Cuántos pies cuadrados tiene?', ['224', '60', '30', '196'], 'Área = largo × ancho = 14 × 16 = 224 pies cuadrados.']],
    ['sqyards', 'math', 'national', 1, 'Licensing exam content outline · Real estate calculations: area',
        ['Carpet for a 15 by 18 foot room is priced per square yard. How many square yards are needed?', ['270', '30', '90', '33'], '15 × 18 = 270 square feet; 270 ÷ 9 = 30 square yards.'],
        ['La alfombra para una habitación de 15 por 18 pies se vende por yarda cuadrada. ¿Cuántas yardas cuadradas se necesitan?', ['270', '30', '90', '33'], '15 × 18 = 270 pies cuadrados; 270 ÷ 9 = 30 yardas cuadradas.']],
    ['triangle-area', 'math', 'national', 2, 'Licensing exam content outline · Real estate calculations: area',
        ['A triangular lot has a base of 200 feet and a height of 150 feet. What is its area?', ['30,000 sq ft', '350 sq ft', '15,000 sq ft', '7,500 sq ft'], 'Triangle area = ½ × base × height = ½ × 200 × 150 = 15,000 square feet.'],
        ['Un lote triangular tiene una base de 200 pies y una altura de 150 pies. ¿Cuál es su área?', ['30,000 pies²', '350 pies²', '15,000 pies²', '7,500 pies²'], 'Área del triángulo = ½ × base × altura = ½ × 200 × 150 = 15,000 pies cuadrados.']],
    ['acres-from-sqft', 'math', 'national', 3, 'Licensing exam content outline · Real estate calculations: area',
        ['A parcel is 660 feet by 330 feet. About how many acres is it?', ['2', '10', '4', '5'], '660 × 330 = 217,800 sq ft; ÷ 43,560 = 5 acres.'],
        ['Un terreno mide 660 por 330 pies. ¿Aproximadamente cuántos acres tiene?', ['2', '10', '4', '5'], '660 × 330 = 217,800 pies²; ÷ 43,560 = 5 acres.']],
    ['price-per-front-foot', 'math', 'national', 0, 'Licensing exam content outline · Real estate calculations: area and price',
        ['A lot with 80 feet of frontage sells for $96,000. What is the price per front foot?', ['$1,200', '$120', '$12,000', '$1,000'], '$96,000 ÷ 80 = $1,200 per front foot.'],
        ['Un lote con 80 pies de frente se vende en $96,000. ¿Cuál es el precio por pie de frente?', ['$1,200', '$120', '$12,000', '$1,000'], '$96,000 ÷ 80 = $1,200 por pie de frente.']],
    ['price-per-sqft', 'math', 'national', 1, 'Licensing exam content outline · Real estate calculations: area and price',
        ['A 2,400 square foot home sells for $336,000. What is the price per square foot?', ['$120', '$140', '$150', '$160'], '$336,000 ÷ 2,400 = $140 per square foot.'],
        ['Una casa de 2,400 pies cuadrados se vende en $336,000. ¿Cuál es el precio por pie cuadrado?', ['$120', '$140', '$150', '$160'], '$336,000 ÷ 2,400 = $140 por pie cuadrado.']],
    ['ltv-loan', 'math', 'national', 2, 'Licensing exam content outline · Real estate calculations: loan-to-value',
        ['A lender will lend 80% of the lesser of price or appraisal. The price is $250,000 and the appraisal $240,000. What is the most it will lend?', ['$200,000', '$250,000', '$192,000', '$240,000'], 'Use the lower value: $240,000 × 0.80 = $192,000.'],
        ['Un prestamista presta el 80% del menor entre el precio y el avalúo. El precio es $250,000 y el avalúo $240,000. ¿Cuánto es lo máximo que prestará?', ['$200,000', '$250,000', '$192,000', '$240,000'], 'Se usa el valor menor: $240,000 × 0.80 = $192,000.']],
    ['down-payment', 'math', 'national', 3, 'Licensing exam content outline · Real estate calculations: loan-to-value',
        ['A buyer pays $320,000 with a 95% loan. How much is the down payment?', ['$32,000', '$3,200', '$304,000', '$16,000'], 'Down payment = 5% × $320,000 = $16,000.'],
        ['Un comprador paga $320,000 con un préstamo del 95%. ¿Cuánto es el enganche?', ['$32,000', '$3,200', '$304,000', '$16,000'], 'Enganche = 5% × $320,000 = $16,000.']],
    ['annual-interest', 'math', 'national', 0, 'Licensing exam content outline · Real estate calculations: interest',
        ['What is the first month\'s interest on a $210,000 loan at 6% annual interest?', ['$1,050', '$12,600', '$1,260', '$105'], '$210,000 × 0.06 = $12,600 a year; ÷ 12 = $1,050.'],
        ['¿Cuál es el interés del primer mes de un préstamo de $210,000 al 6% anual?', ['$1,050', '$12,600', '$1,260', '$105'], '$210,000 × 0.06 = $12,600 al año; ÷ 12 = $1,050.']],
    ['principal-paid', 'math', 'national', 1, 'Licensing exam content outline · Real estate calculations: interest and amortization',
        ['A $150,000 loan at 6% has a monthly principal and interest payment of $899.33. How much principal is paid in month one?', ['$750.00', '$149.33', '$899.33', '$74.93'], 'Interest = $150,000 × 0.06 ÷ 12 = $750; principal = $899.33 − $750 = $149.33.'],
        ['Un préstamo de $150,000 al 6% tiene un pago mensual de capital e interés de $899.33. ¿Cuánto capital se paga el primer mes?', ['$750.00', '$149.33', '$899.33', '$74.93'], 'Interés = $150,000 × 0.06 ÷ 12 = $750; capital = $899.33 − $750 = $149.33.']],
    ['points-cost', 'math', 'national', 2, 'Licensing exam content outline · Real estate calculations: points',
        ['How much do 2 discount points cost on a $275,000 loan?', ['$2,750', '$550', '$5,500', '$27,500'], 'One point is 1% of the loan: 2 × $2,750 = $5,500.'],
        ['¿Cuánto cuestan 2 puntos de descuento en un préstamo de $275,000?', ['$2,750', '$550', '$5,500', '$27,500'], 'Un punto es el 1% del préstamo: 2 × $2,750 = $5,500.']],
    ['tax-mills', 'math', 'national', 3, 'Licensing exam content outline · Real estate calculations: property tax',
        ['A home is assessed at $180,000 and the tax rate is 25 mills. What is the annual tax?', ['$450', '$45,000', '$720', '$4,500'], '25 mills = $0.025 per dollar: $180,000 × 0.025 = $4,500.'],
        ['Una casa está tasada en $180,000 y la tasa de impuesto es de 25 milésimos (mills). ¿Cuál es el impuesto anual?', ['$450', '$45,000', '$720', '$4,500'], '25 milésimos = $0.025 por dólar: $180,000 × 0.025 = $4,500.']],
    ['tax-per-hundred', 'math', 'national', 0, 'Licensing exam content outline · Real estate calculations: property tax',
        ['The tax rate is $2.40 per $100 of assessed value, and the assessed value is $225,000. What is the annual tax?', ['$5,400', '$540', '$2,400', '$54,000'], '$225,000 ÷ 100 = 2,250; × $2.40 = $5,400.'],
        ['La tasa de impuesto es $2.40 por cada $100 del valor tasado, y el valor tasado es $225,000. ¿Cuál es el impuesto anual?', ['$5,400', '$540', '$2,400', '$54,000'], '$225,000 ÷ 100 = 2,250; × $2.40 = $5,400.']],
    ['assessment-ratio', 'math', 'national', 1, 'Licensing exam content outline · Real estate calculations: property tax',
        ['Market value is $300,000, assessed at 80%, with a tax rate of 2%. What is the annual tax?', ['$6,000', '$4,800', '$2,400', '$24,000'], 'Assessed value = $300,000 × 0.80 = $240,000; × 0.02 = $4,800.'],
        ['El valor de mercado es $300,000, se tasa al 80% y la tasa de impuesto es 2%. ¿Cuál es el impuesto anual?', ['$6,000', '$4,800', '$2,400', '$24,000'], 'Valor tasado = $300,000 × 0.80 = $240,000; × 0.02 = $4,800.']],
    ['cap-value', 'math', 'national', 2, 'Licensing exam content outline · Real estate calculations: income approach',
        ['A building nets $54,000 a year. At a 9% capitalization rate, what is its value?', ['$486,000', '$540,000', '$600,000', '$4,860'], 'Value = net operating income ÷ cap rate = $54,000 ÷ 0.09 = $600,000.'],
        ['Un edificio produce un ingreso neto de $54,000 al año. Con una tasa de capitalización del 9%, ¿cuál es su valor?', ['$486,000', '$540,000', '$600,000', '$4,860'], 'Valor = ingreso operativo neto ÷ tasa de capitalización = $54,000 ÷ 0.09 = $600,000.']],
    ['noi', 'math', 'national', 3, 'Licensing exam content outline · Real estate calculations: income approach',
        ['Gross potential income is $120,000, vacancy is 5%, and operating expenses are $40,000. What is the net operating income?', ['$80,000', '$114,000', '$76,000', '$74,000'], 'Effective gross = $120,000 − $6,000 = $114,000; NOI = $114,000 − $40,000 = $74,000.'],
        ['El ingreso bruto potencial es $120,000, la desocupación es 5% y los gastos operativos son $40,000. ¿Cuál es el ingreso operativo neto?', ['$80,000', '$114,000', '$76,000', '$74,000'], 'Ingreso bruto efectivo = $120,000 − $6,000 = $114,000; ingreso neto = $114,000 − $40,000 = $74,000.']],
    ['grm', 'math', 'national', 0, 'Licensing exam content outline · Real estate calculations: gross rent multiplier',
        ['A home rents for $1,500 a month. Comparable homes sell at a gross rent multiplier of 150. What is its estimated value?', ['$225,000', '$22,500', '$180,000', '$150,000'], 'Value = monthly rent × GRM = $1,500 × 150 = $225,000.'],
        ['Una casa se renta en $1,500 al mes. Las casas comparables se venden con un multiplicador de renta bruta de 150. ¿Cuál es su valor estimado?', ['$225,000', '$22,500', '$180,000', '$150,000'], 'Valor = renta mensual × multiplicador = $1,500 × 150 = $225,000.']],
    ['depreciation-straight', 'math', 'national', 1, 'Licensing exam content outline · Real estate calculations: depreciation',
        ['A $400,000 building has a 40-year economic life. Using straight-line depreciation, what is its value after 10 years?', ['$100,000', '$300,000', '$360,000', '$390,000'], '$400,000 ÷ 40 = $10,000 a year; × 10 = $100,000; $400,000 − $100,000 = $300,000.'],
        ['Un edificio de $400,000 tiene una vida económica de 40 años. Con depreciación lineal, ¿cuál es su valor después de 10 años?', ['$100,000', '$300,000', '$360,000', '$390,000'], '$400,000 ÷ 40 = $10,000 al año; × 10 = $100,000; $400,000 − $100,000 = $300,000.']],
    ['cost-approach', 'math', 'national', 2, 'Licensing exam content outline · Real estate calculations: cost approach',
        ['A new building would cost $350,000; depreciation is $50,000; the land is worth $90,000. What is the value by the cost approach?', ['$490,000', '$300,000', '$390,000', '$260,000'], 'Value = cost − depreciation + land = $350,000 − $50,000 + $90,000 = $390,000.'],
        ['Construir un edificio nuevo costaría $350,000; la depreciación es $50,000; el terreno vale $90,000. ¿Cuál es el valor por el enfoque de costo?', ['$490,000', '$300,000', '$390,000', '$260,000'], 'Valor = costo − depreciación + terreno = $350,000 − $50,000 + $90,000 = $390,000.']],
    ['appreciation', 'math', 'national', 3, 'Licensing exam content outline · Real estate calculations: appreciation',
        ['A home bought for $200,000 rises 5% a year for 2 years, compounded. What is it worth?', ['$210,000', '$220,000', '$215,000', '$220,500'], 'Year 1: $210,000; year 2: $210,000 × 1.05 = $220,500.'],
        ['Una casa comprada en $200,000 sube 5% al año durante 2 años, de forma compuesta. ¿Cuánto vale?', ['$210,000', '$220,000', '$215,000', '$220,500'], 'Año 1: $210,000; año 2: $210,000 × 1.05 = $220,500.']],
    ['percent-profit', 'math', 'national', 0, 'Licensing exam content outline · Real estate calculations: profit and loss',
        ['An investor buys for $160,000 and sells for $200,000. What is the percent of profit?', ['25%', '20%', '40%', '80%'], 'Profit = $40,000; ÷ cost $160,000 = 25%. Always divide by what was paid.'],
        ['Un inversionista compra en $160,000 y vende en $200,000. ¿Cuál es el porcentaje de ganancia?', ['25%', '20%', '40%', '80%'], 'Ganancia = $40,000; ÷ costo $160,000 = 25%. Siempre se divide entre lo que se pagó.']],
    ['loss-original', 'math', 'national', 1, 'Licensing exam content outline · Real estate calculations: profit and loss',
        ['A home sold for $243,000, a 10% loss on what the owner paid. What did the owner pay?', ['$267,300', '$270,000', '$218,700', '$253,000'], 'Sale = 90% of cost; cost = $243,000 ÷ 0.90 = $270,000.'],
        ['Una casa se vendió en $243,000, con una pérdida del 10% sobre lo que pagó el dueño. ¿Cuánto pagó el dueño?', ['$267,300', '$270,000', '$218,700', '$253,000'], 'Venta = 90% del costo; costo = $243,000 ÷ 0.90 = $270,000.']],
    ['proration-tax-seller', 'math', 'national', 2, 'Licensing exam content outline · Real estate calculations: prorations',
        ['Annual taxes of $3,650 are paid in arrears. Closing is on April 30, with the seller paying through the closing day. Using a 365-day year, how much does the seller owe (Jan 1 to Apr 30 is 120 days)?', ['$3,650', '$2,450', '$1,200', '$1,216.67'], '$3,650 ÷ 365 = $10 a day; × 120 days = $1,200 credit to the buyer.'],
        ['Los impuestos anuales de $3,650 se pagan al vencimiento del año. El cierre es el 30 de abril y el vendedor paga hasta el día del cierre. Con un año de 365 días, ¿cuánto debe el vendedor (del 1 de enero al 30 de abril son 120 días)?', ['$3,650', '$2,450', '$1,200', '$1,216.67'], '$3,650 ÷ 365 = $10 al día; × 120 días = $1,200 de crédito al comprador.']],
    ['proration-rent', 'math', 'national', 3, 'Licensing exam content outline · Real estate calculations: prorations',
        ['The seller collected $1,800 rent for June. Closing is June 21 and the buyer owns from that day. Using a 30-day month, how much rent is credited to the buyer?', ['$1,200', '$600', '$1,260', '$600 debit to the buyer'], 'The buyer owns 10 days (June 21 to 30): $1,800 ÷ 30 = $60; × 10 = $600 credited to the buyer.'],
        ['El vendedor cobró $1,800 de renta de junio. El cierre es el 21 de junio y el comprador es dueño desde ese día. Con un mes de 30 días, ¿cuánta renta se acredita al comprador?', ['$1,200', '$600', '$1,260', '$600 de cargo al comprador'], 'El comprador es dueño 10 días (del 21 al 30 de junio): $1,800 ÷ 30 = $60; × 10 = $600 acreditados al comprador.']],
    ['income-qualify', 'math', 'national', 0, 'Licensing exam content outline · Real estate calculations: qualifying',
        ['A lender allows housing costs of 28% of gross income. A buyer earns $90,000 a year. What is the maximum monthly housing payment?', ['$2,100', '$2,520', '$25,200', '$2,800'], '$90,000 ÷ 12 = $7,500 a month; × 0.28 = $2,100.'],
        ['Un prestamista permite gastos de vivienda del 28% del ingreso bruto. Un comprador gana $90,000 al año. ¿Cuál es el pago mensual máximo de vivienda?', ['$2,100', '$2,520', '$25,200', '$2,800'], '$90,000 ÷ 12 = $7,500 al mes; × 0.28 = $2,100.']],
    ['volume', 'math', 'national', 1, 'Licensing exam content outline · Real estate calculations: volume',
        ['A slab is 30 feet by 20 feet and 6 inches thick. How many cubic yards of concrete are needed (rounded)?', ['300', '11', '33', '100'], '30 × 20 × 0.5 = 300 cubic feet; ÷ 27 = 11.1, about 11 cubic yards.'],
        ['Una losa mide 30 por 20 pies y tiene 6 pulgadas de grosor. ¿Cuántas yardas cúbicas de concreto se necesitan (redondeado)?', ['300', '11', '33', '100'], '30 × 20 × 0.5 = 300 pies cúbicos; ÷ 27 = 11.1, unas 11 yardas cúbicas.']],
    ['equity', 'math', 'national', 2, 'Licensing exam content outline · Real estate calculations: equity',
        ['A home is worth $350,000 and the owner owes $210,000. What is the owner\'s equity?', ['$350,000', '$210,000', '$140,000', '$560,000'], 'Equity = market value − debt = $350,000 − $210,000 = $140,000.'],
        ['Una casa vale $350,000 y el dueño debe $210,000. ¿Cuál es el capital (equity) del dueño?', ['$350,000', '$210,000', '$140,000', '$560,000'], 'Capital = valor de mercado − deuda = $350,000 − $210,000 = $140,000.']],
    ['cap-rate-find', 'math', 'national', 3, 'Licensing exam content outline · Real estate calculations: income approach',
        ['A property sold for $800,000 and earns net operating income of $64,000. What is the capitalization rate?', ['6%', '7%', '12.5%', '8%'], 'Rate = income ÷ value = $64,000 ÷ $800,000 = 0.08, or 8%.'],
        ['Una propiedad se vendió en $800,000 y genera un ingreso operativo neto de $64,000. ¿Cuál es la tasa de capitalización?', ['6%', '7%', '12.5%', '8%'], 'Tasa = ingreso ÷ valor = $64,000 ÷ $800,000 = 0.08, o 8%.']],
    ['half-section', 'math', 'national', 0, 'Licensing exam content outline · Real estate calculations: area',
        ['How many acres are in the NE ¼ of the SW ¼ of a section?', ['40', '160', '80', '10'], 'A section is 640 acres: 640 ÷ 4 = 160; ÷ 4 = 40 acres.'],
        ['¿Cuántos acres hay en el NE ¼ del SO ¼ de una sección?', ['40', '160', '80', '10'], 'Una sección tiene 640 acres: 640 ÷ 4 = 160; ÷ 4 = 40 acres.']],
    ['rate-of-return', 'math', 'national', 1, 'Licensing exam content outline · Real estate calculations: investment',
        ['An investor puts $50,000 into a property that yields $4,000 a year in cash flow. What is the rate of return on the cash invested?', ['4%', '8%', '12.5%', '0.8%'], 'Cash on cash = $4,000 ÷ $50,000 = 0.08, or 8%.'],
        ['Un inversionista pone $50,000 en una propiedad que genera $4,000 al año de flujo de efectivo. ¿Cuál es el rendimiento sobre el efectivo invertido?', ['4%', '8%', '12.5%', '0.8%'], 'Rendimiento = $4,000 ÷ $50,000 = 0.08, o 8%.']],
    ['transfer-tax', 'math', 'national', 2, 'Licensing exam content outline · Real estate calculations: closing costs',
        ['A state charges a transfer tax of $1 per $500 of price. The price is $240,000. What is the tax?', ['$240', '$120', '$480', '$4,800'], '$240,000 ÷ 500 = 480 units; × $1 = $480.'],
        ['Un estado cobra un impuesto de transferencia de $1 por cada $500 del precio. El precio es $240,000. ¿Cuál es el impuesto?', ['$240', '$120', '$480', '$4,800'], '$240,000 ÷ 500 = 480 unidades; × $1 = $480.']],
    // state_rules (state)
    ['trec-members', 'state_rules', 'state', 2, 'Texas Occupations Code §1101.051',
        ['How many members serve on the Texas Real Estate Commission?', ['5', '7', '9', '12'], 'TREC has nine members appointed by the governor: six brokers and three public members.'],
        ['¿Cuántos miembros tiene la Comisión de Bienes Raíces de Texas (TREC)?', ['5', '7', '9', '12'], 'TREC tiene nueve miembros nombrados por el gobernador: seis brókeres y tres miembros del público.']],
    ['trec-appoints', 'state_rules', 'state', 0, 'Texas Occupations Code §1101.051',
        ['Who appoints the members of TREC?', ['The governor, with the advice and consent of the Senate', 'The Texas REALTORS® association', 'The attorney general', 'The voters'], 'Commissioners are appointed by the governor with the Senate\'s advice and consent.'],
        ['¿Quién nombra a los miembros de TREC?', ['El gobernador, con el consejo y consentimiento del Senado', 'La asociación Texas REALTORS®', 'El fiscal general', 'Los votantes'], 'Los comisionados los nombra el gobernador con el consejo y consentimiento del Senado.']],
    ['trec-public', 'state_rules', 'state', 1, 'Texas Occupations Code §1101.051',
        ['How many TREC members are public members rather than brokers?', ['None', '3', '6', '4'], 'Six members are brokers with at least 5 years of experience; three represent the public.'],
        ['¿Cuántos miembros de TREC son miembros del público y no brókeres?', ['Ninguno', '3', '6', '4'], 'Seis miembros son brókeres con al menos 5 años de experiencia; tres representan al público.']],
    ['qualifying-courses', 'state_rules', 'state', 3, 'Texas Occupations Code Chapter 1101; TREC qualifying education rules (22 TAC Chapter 535)',
        ['Which course is NOT one of the six 30-hour qualifying courses for a Texas sales agent license?', ['Law of Agency', 'Promulgated Contract Forms', 'Real Estate Finance', 'Property Management'], 'The six are Principles I and II, Law of Agency, Law of Contracts, Promulgated Contract Forms and Real Estate Finance.'],
        ['¿Qué curso NO es uno de los seis cursos de precalificación de 30 horas para la licencia de agente de ventas en Texas?', ['Ley de Agencia', 'Formularios de Contrato Promulgados', 'Finanzas Inmobiliarias', 'Administración de Propiedades'], 'Los seis son Principios I y II, Ley de Agencia, Ley de Contratos, Formularios de Contrato Promulgados y Finanzas Inmobiliarias.']],
    ['sae-hours', 'state_rules', 'state', 0, 'TREC Rules, 22 TAC Chapter 535 (Sales Agent Apprentice Education)',
        ['Before a sales agent\'s first license renewal, how many hours of Sales Agent Apprentice Education (SAE) are required?', ['98', '18', '180', '30'], 'A new sales agent completes 98 hours of SAE before the first renewal.'],
        ['Antes de la primera renovación de su licencia, ¿cuántas horas de Educación de Aprendiz de Agente de Ventas (SAE) necesita un agente de ventas?', ['98', '18', '180', '30'], 'Un agente de ventas nuevo completa 98 horas de SAE antes de su primera renovación.']],
    ['ce-hours', 'state_rules', 'state', 1, 'TREC Rules, 22 TAC §535.92',
        ['After the first renewal, a sales agent needs how many hours of continuing education every 2 years?', ['8', '18', '30', '15'], 'Each 2-year renewal needs 18 hours of CE, including the 8 hours of Legal Update I and II.'],
        ['Después de la primera renovación, ¿cuántas horas de educación continua necesita un agente de ventas cada 2 años?', ['8', '18', '30', '15'], 'Cada renovación de 2 años requiere 18 horas de CE, incluidas las 8 horas de Actualización Legal I y II.']],
    ['legal-update', 'state_rules', 'state', 2, 'TREC Rules, 22 TAC §535.92',
        ['Which courses must be part of every Texas license holder\'s CE for renewal?', ['Real Estate Finance', 'Property Management', 'Legal Update I and II', 'Principles of Real Estate'], 'TREC Legal Update I and II (4 hours each) are required in each CE cycle.'],
        ['¿Qué cursos deben formar parte de la CE de todo agente con licencia en Texas para renovar?', ['Finanzas Inmobiliarias', 'Administración de Propiedades', 'Actualización Legal I y II', 'Principios de Bienes Raíces'], 'La Actualización Legal I y II de TREC (4 horas cada una) es obligatoria en cada ciclo de CE.']],
    ['brc', 'state_rules', 'state', 3, 'TREC Rules, 22 TAC §535.92',
        ['Which license holders must complete the 6-hour Broker Responsibility Course?', ['Every sales agent', 'Only new sales agents', 'Only inspectors', 'Brokers who sponsor agents and delegated supervisors'], 'The Broker Responsibility Course is required for designated and sponsoring brokers and those who supervise agents.'],
        ['¿Qué agentes con licencia deben completar el Curso de Responsabilidad del Bróker de 6 horas?', ['Todos los agentes de ventas', 'Solo los agentes de ventas nuevos', 'Solo los inspectores', 'Los brókeres que patrocinan agentes y los supervisores delegados'], 'El Curso de Responsabilidad del Bróker es obligatorio para brókeres designados y patrocinadores y para quienes supervisan agentes.']],
    ['license-term', 'state_rules', 'state', 0, 'Texas Occupations Code Chapter 1101; TREC Rules, 22 TAC §535.91',
        ['A Texas real estate license is generally valid for', ['2 years', '1 year', '3 years', '4 years'], 'Licenses are issued for 2-year terms and renewed every 2 years.'],
        ['Una licencia de bienes raíces de Texas en general es válida por', ['2 años', '1 año', '3 años', '4 años'], 'Las licencias se emiten por periodos de 2 años y se renuevan cada 2 años.']],
    ['exam-window', 'state_rules', 'state', 1, 'TREC Rules, 22 TAC Chapter 535 (license applications)',
        ['After TREC approves a license application, the applicant must pass the exam within', ['6 months', '1 year', '2 years', '90 days'], 'An application is valid for 1 year; the exam must be passed within that time.'],
        ['Después de que TREC aprueba una solicitud de licencia, el solicitante debe aprobar el examen dentro de', ['6 meses', '1 año', '2 años', '90 días'], 'La solicitud es válida por 1 año; el examen debe aprobarse dentro de ese plazo.']],
    ['fitness', 'state_rules', 'state', 2, 'Texas Occupations Code §1101.353',
        ['A person unsure whether a past criminal conviction will block a license can ask TREC, before applying, for', ['a waiver of the exam', 'a broker sponsorship', 'a fitness (moral character) determination', 'an inactive license'], 'TREC offers a fitness determination so a person can learn whether they qualify before taking the courses.'],
        ['Una persona que no sabe si una condena penal anterior le impedirá obtener la licencia puede pedir a TREC, antes de solicitarla,', ['una exención del examen', 'el patrocinio de un bróker', 'una determinación de idoneidad (carácter moral)', 'una licencia inactiva'], 'TREC ofrece una determinación de idoneidad para que la persona sepa si califica antes de tomar los cursos.']],
    ['sponsor-active', 'state_rules', 'state', 3, 'Texas Occupations Code §1101.351',
        ['A Texas sales agent may act for others in real estate transactions only when', ['the agent has passed the exam', 'the agent holds a broker license', 'the agent has an office', 'the agent is sponsored by a licensed broker'], 'A sales agent\'s license is active only when a broker sponsors the agent.'],
        ['Un agente de ventas de Texas puede actuar por otros en operaciones inmobiliarias solo cuando', ['aprobó el examen', 'tiene licencia de bróker', 'tiene una oficina', 'lo patrocina un bróker con licencia'], 'La licencia de un agente de ventas solo está activa cuando un bróker lo patrocina.']],
    ['one-sponsor', 'state_rules', 'state', 0, 'Texas Occupations Code §1101.351; TREC Rules, 22 TAC §535.2',
        ['A Texas sales agent may be sponsored by', ['only one broker at a time', 'up to two brokers', 'any number of brokers', 'a title company'], 'Each sales agent has one sponsoring broker at a time.'],
        ['Un agente de ventas de Texas puede ser patrocinado por', ['un solo bróker a la vez', 'hasta dos brókeres', 'cualquier número de brókeres', 'una compañía de títulos'], 'Cada agente de ventas tiene un solo bróker patrocinador a la vez.']],
    ['broker-experience', 'state_rules', 'state', 1, 'Texas Occupations Code §1101.356',
        ['To apply for a Texas broker license, an applicant generally needs active experience as a license holder for at least', ['2 years in the last 3', '4 years in the last 5', '5 years in the last 10', '1 year'], 'A broker applicant needs at least 4 years of active experience in the 5 years before applying.'],
        ['Para solicitar la licencia de bróker en Texas, el solicitante en general necesita experiencia activa como agente con licencia de al menos', ['2 años en los últimos 3', '4 años en los últimos 5', '5 años en los últimos 10', '1 año'], 'El solicitante a bróker necesita al menos 4 años de experiencia activa en los 5 años anteriores a la solicitud.']],
    ['broker-education', 'state_rules', 'state', 2, 'Texas Occupations Code §1101.356',
        ['How many total classroom hours of education does a Texas broker applicant need?', ['180', '270', '900', '630'], 'Broker applicants need 900 hours: 270 hours of qualifying courses and 630 hours of related courses.'],
        ['¿Cuántas horas totales de educación necesita un solicitante a bróker en Texas?', ['180', '270', '900', '630'], 'Los solicitantes a bróker necesitan 900 horas: 270 de cursos de precalificación y 630 de cursos relacionados.']],
    ['who-needs-license', 'state_rules', 'state', 3, 'Texas Occupations Code §1101.002; §1101.351',
        ['Which person needs a Texas real estate license?', ['An owner selling the owner\'s own home', 'An attorney acting for a client', 'A court-appointed executor selling estate property', 'A person who negotiates sales for others for a fee'], 'Negotiating real estate transactions for others for compensation requires a license. Owners, attorneys and court officers are exempt.'],
        ['¿Qué persona necesita una licencia de bienes raíces de Texas?', ['Un dueño que vende su propia casa', 'Un abogado que actúa por un cliente', 'Un albacea nombrado por el tribunal que vende bienes de la herencia', 'Una persona que negocia ventas para otros a cambio de un pago'], 'Negociar operaciones inmobiliarias para otros a cambio de una compensación requiere licencia. Los dueños, abogados y funcionarios judiciales están exentos.']],
    ['unlicensed-penalty', 'state_rules', 'state', 0, 'Texas Occupations Code §1101.758',
        ['A first offense of acting as a broker or sales agent without a license in Texas is', ['a Class A misdemeanor', 'a civil fine only', 'a third-degree felony', 'not punishable'], 'Unlicensed activity is a Class A misdemeanor; a repeat offense is a third-degree felony.'],
        ['La primera infracción por actuar como bróker o agente de ventas sin licencia en Texas es', ['un delito menor Clase A', 'solo una multa civil', 'un delito grave de tercer grado', 'no sancionable'], 'La actividad sin licencia es un delito menor Clase A; la reincidencia es un delito grave de tercer grado.']],
    ['admin-penalty', 'state_rules', 'state', 1, 'Texas Occupations Code §1101.702',
        ['TREC may assess an administrative penalty of up to how much per violation, with each day a separate violation?', ['$1,000', '$5,000', '$10,000', '$50,000'], 'The administrative penalty is up to $5,000 per violation, and each day of a continuing violation counts separately.'],
        ['¿Hasta cuánto puede imponer TREC como multa administrativa por cada infracción, contando cada día como una infracción distinta?', ['$1,000', '$5,000', '$10,000', '$50,000'], 'La multa administrativa es de hasta $5,000 por infracción, y cada día de una infracción continua cuenta por separado.']],
    ['compensation-unlicensed', 'state_rules', 'state', 2, 'Texas Occupations Code §1101.651',
        ['A Texas broker may pay a referral fee to', ['the broker\'s unlicensed neighbor', 'an unlicensed assistant who brings in buyers', 'another licensed broker', 'a buyer\'s unlicensed cousin who found the home'], 'Brokers may not pay compensation for brokerage to unlicensed people; a licensed broker may receive it.'],
        ['Un bróker de Texas puede pagar una comisión por recomendación a', ['su vecino sin licencia', 'un asistente sin licencia que trae compradores', 'otro bróker con licencia', 'un primo sin licencia del comprador que encontró la casa'], 'Los brókeres no pueden pagar compensación por corretaje a personas sin licencia; un bróker con licencia sí puede recibirla.']],
    ['agent-paid-by-broker', 'state_rules', 'state', 3, 'Texas Occupations Code §1101.651',
        ['A Texas sales agent may accept compensation for a real estate transaction only from', ['the buyer directly', 'the seller directly', 'the title company', 'the agent\'s sponsoring broker'], 'Sales agents are paid through their sponsoring broker, not by the parties.'],
        ['Un agente de ventas de Texas puede aceptar compensación por una operación inmobiliaria solo de', ['el comprador directamente', 'el vendedor directamente', 'la compañía de títulos', 'su bróker patrocinador'], 'Los agentes de ventas reciben su pago por medio de su bróker patrocinador, no de las partes.']],
    ['commission-suit', 'state_rules', 'state', 0, 'Texas Occupations Code §1101.806',
        ['To sue in Texas for a commission, a broker needs', ['a written agreement signed by the person to be charged', 'an oral promise witnessed by two people', 'a recorded deed', 'a closing statement only'], 'A commission is enforceable only if the promise is in writing and signed by the party to be charged.'],
        ['Para demandar una comisión en Texas, el bróker necesita', ['un acuerdo por escrito firmado por la persona a quien se cobra', 'una promesa verbal ante dos testigos', 'una escritura inscrita', 'solo una declaración de cierre'], 'La comisión solo es exigible si la promesa consta por escrito y la firma la parte a quien se cobra.']],
    ['agent-sue', 'state_rules', 'state', 1, 'Texas Occupations Code §1101.806',
        ['Who may sue a client in Texas to collect a commission?', ['The sales agent who did the work', 'The broker', 'The buyer\'s lender', 'TREC'], 'Only the broker can sue for a commission; a sales agent is paid through the broker.'],
        ['¿Quién puede demandar a un cliente en Texas para cobrar una comisión?', ['El agente de ventas que hizo el trabajo', 'El bróker', 'El prestamista del comprador', 'TREC'], 'Solo el bróker puede demandar una comisión; el agente de ventas cobra por medio del bróker.']],
    ['recovery-per-transaction', 'state_rules', 'state', 2, 'Texas Occupations Code §1101.610',
        ['The most the Real Estate Recovery Trust Account pays for claims from one transaction is', ['$25,000', '$100,000', '$50,000', '$10,000'], 'Payments are limited to $50,000 per transaction and $100,000 per license holder.'],
        ['Lo máximo que paga la Cuenta Fiduciaria de Recuperación de Bienes Raíces por reclamos de una sola operación es', ['$25,000', '$100,000', '$50,000', '$10,000'], 'Los pagos se limitan a $50,000 por operación y $100,000 por agente con licencia.']],
    ['recovery-per-licensee', 'state_rules', 'state', 3, 'Texas Occupations Code §1101.610',
        ['The Recovery Trust Account\'s total limit for claims against one license holder is', ['$50,000', '$25,000', '$250,000', '$100,000'], 'No more than $100,000 is paid for one license holder.'],
        ['El límite total de la Cuenta Fiduciaria de Recuperación para reclamos contra un solo agente con licencia es', ['$50,000', '$25,000', '$250,000', '$100,000'], 'No se pagan más de $100,000 por un solo agente con licencia.']],
    ['recovery-revocation', 'state_rules', 'state', 0, 'Texas Occupations Code Chapter 1101, Subchapter M',
        ['When the Recovery Trust Account pays a claim against a license holder, the license', ['is revoked until the license holder repays the amount with interest', 'is unaffected', 'is placed on probation for 30 days', 'is converted to inactive status'], 'Payment from the account leads to revocation until the license holder repays it with interest.'],
        ['Cuando la Cuenta Fiduciaria de Recuperación paga un reclamo contra un agente con licencia, la licencia', ['se revoca hasta que el agente devuelva el monto con intereses', 'no se ve afectada', 'queda en libertad condicional por 30 días', 'pasa a estado inactivo'], 'El pago de la cuenta lleva a la revocación hasta que el agente lo devuelva con intereses.']],
    ['recovery-judgment', 'state_rules', 'state', 1, 'Texas Occupations Code Chapter 1101, Subchapter M',
        ['To collect from the Recovery Trust Account, a consumer first needs', ['a complaint filed with TREC only', 'a final court judgment against the license holder', 'the broker\'s written permission', 'a title insurance claim'], 'The consumer must get a court judgment for a violation of the law and be unable to collect it.'],
        ['Para cobrar de la Cuenta Fiduciaria de Recuperación, el consumidor primero necesita', ['solo una queja presentada ante TREC', 'una sentencia judicial firme contra el agente con licencia', 'el permiso por escrito del bróker', 'un reclamo al seguro de título'], 'El consumidor debe obtener una sentencia judicial por una infracción de la ley y no poder cobrarla.']],
    ['broker-lawyer', 'state_rules', 'state', 2, 'Texas Occupations Code §1101.251',
        ['Texas promulgated contract forms are drafted by', ['the State Bar alone', 'Texas REALTORS®', 'the Broker-Lawyer Committee', 'the Texas Legislature'], 'The Broker-Lawyer Committee drafts and revises forms that TREC then promulgates.'],
        ['Los formularios de contrato promulgados de Texas los redacta', ['solo el Colegio de Abogados', 'Texas REALTORS®', 'el Comité de Brókeres y Abogados', 'la Legislatura de Texas'], 'El Comité de Brókeres y Abogados redacta y revisa los formularios que TREC luego promulga.']],
    ['talcb', 'state_rules', 'state', 3, 'Texas Occupations Code Chapter 1103',
        ['Real estate appraisers in Texas are licensed and certified by', ['TREC\'s inspector division', 'the Texas Department of Insurance', 'each county appraisal district', 'the Texas Appraiser Licensing and Certification Board'], 'TALCB, attached to TREC, regulates appraisers and appraisal management companies.'],
        ['En Texas, los tasadores de bienes raíces son licenciados y certificados por', ['la división de inspectores de TREC', 'el Departamento de Seguros de Texas', 'cada distrito de avalúo del condado', 'la Junta de Licencias y Certificación de Tasadores de Texas (TALCB)'], 'TALCB, adscrita a TREC, regula a los tasadores y a las empresas de administración de avalúos.']],
    ['trec-inspectors', 'state_rules', 'state', 0, 'Texas Occupations Code Chapter 1102',
        ['Which professionals does TREC also license in Texas?', ['Real estate inspectors', 'Mortgage loan originators', 'Title insurance agents', 'Home builders'], 'TREC licenses inspectors and registers easement or right-of-way agents and residential service companies.'],
        ['¿Qué otros profesionales autoriza TREC en Texas?', ['Inspectores de bienes raíces', 'Originadores de préstamos hipotecarios', 'Agentes de seguros de título', 'Constructores de vivienda'], 'TREC otorga licencias a inspectores y registra a agentes de servidumbres o derechos de paso y a empresas de servicios residenciales.']],
    ['title-rates', 'state_rules', 'state', 1, 'Texas Insurance Code Title 11',
        ['Title insurance premiums in Texas are', ['negotiated by the buyer\'s agent', 'set (promulgated) by the Texas Department of Insurance', 'set by each title company', 'set by TREC'], 'Texas promulgates title insurance rates, so the premium is the same from any title company.'],
        ['Las primas del seguro de título en Texas', ['las negocia el agente del comprador', 'las fija (promulga) el Departamento de Seguros de Texas', 'las fija cada compañía de títulos', 'las fija TREC'], 'Texas promulga las tarifas del seguro de título, así que la prima es la misma en cualquier compañía de títulos.']],
    ['records-years', 'state_rules', 'state', 2, 'TREC Rules, 22 TAC §535.2',
        ['A Texas broker must keep transaction records for at least', ['1 year', '2 years', '4 years', '10 years'], 'Brokers keep records of each transaction for at least 4 years.'],
        ['Un bróker de Texas debe conservar los registros de cada operación al menos', ['1 año', '2 años', '4 años', '10 años'], 'Los brókeres conservan los registros de cada operación al menos 4 años.']],
    ['broker-supervision', 'state_rules', 'state', 3, 'TREC Rules, 22 TAC §535.2',
        ['Under TREC rules, who is responsible for the authorized acts of a sales agent?', ['The agent alone', 'The client', 'The title company', 'The sponsoring broker'], 'A broker is responsible for the authorized acts of the broker\'s sales agents and must supervise them.'],
        ['Según las reglas de TREC, ¿quién es responsable de los actos autorizados de un agente de ventas?', ['Solo el agente', 'El cliente', 'La compañía de títulos', 'El bróker patrocinador'], 'El bróker es responsable de los actos autorizados de sus agentes de ventas y debe supervisarlos.']],
    ['designated-broker', 'state_rules', 'state', 0, 'Texas Occupations Code §1101.355',
        ['A business entity licensed as a Texas broker must have', ['a designated broker who is an officer, manager or general partner', 'at least three sales agents', 'an office in Austin', 'a lawyer on staff'], 'The entity acts through a designated broker, an individual licensed broker who is an officer, manager or general partner.'],
        ['Una entidad comercial con licencia de bróker en Texas debe tener', ['un bróker designado que sea funcionario, gerente o socio general', 'al menos tres agentes de ventas', 'una oficina en Austin', 'un abogado en su personal'], 'La entidad actúa por medio de un bróker designado, una persona con licencia de bróker que es funcionario, gerente o socio general.']],
    ['unlicensed-assistant', 'state_rules', 'state', 1, 'Texas Occupations Code §1101.351',
        ['An unlicensed assistant in a Texas brokerage may', ['show homes to buyers', 'schedule appointments and do clerical work', 'negotiate offers', 'hold open houses and answer price questions'], 'Showing property, negotiating and answering questions about terms require a license.'],
        ['Un asistente sin licencia en una agencia de Texas puede', ['mostrar casas a compradores', 'programar citas y hacer trabajo administrativo', 'negociar ofertas', 'hacer casas abiertas y responder preguntas de precio'], 'Mostrar propiedades, negociar y responder preguntas sobre términos requiere licencia.']],
    ['own-behalf', 'state_rules', 'state', 2, 'TREC Rules, 22 TAC §535.144',
        ['A Texas license holder buys a home for himself from an unrepresented seller. He must', ['say nothing, since he is a principal', 'use only verbal notice', 'disclose in writing that he holds a real estate license', 'get TREC approval'], 'License holders acting for themselves must disclose their license status in writing before entering a contract.'],
        ['Un agente con licencia de Texas compra una casa para sí mismo a un vendedor no representado. Debe', ['no decir nada, porque es una parte principal', 'avisar solo de palabra', 'divulgar por escrito que tiene licencia de bienes raíces', 'obtener la aprobación de TREC'], 'Los agentes que actúan por su cuenta deben divulgar por escrito su condición de agente con licencia antes de firmar un contrato.']],
    ['practice-law', 'state_rules', 'state', 3, 'Texas Occupations Code §1101.654; TREC Rules, 22 TAC §537.11',
        ['A Texas sales agent filling in a promulgated contract may', ['write a custom clause on how to hold title', 'advise on the tax effects of the sale', 'draft a special provision that needs legal judgment', 'insert factual statements and business details the parties want'], 'Agents may fill in factual statements and business details but may not draft provisions that require legal advice.'],
        ['Un agente de ventas de Texas que llena un contrato promulgado puede', ['escribir una cláusula a medida sobre cómo tener la titularidad', 'asesorar sobre los efectos fiscales de la venta', 'redactar una disposición especial que requiere criterio legal', 'insertar declaraciones de hechos y detalles comerciales que las partes deseen'], 'Los agentes pueden llenar declaraciones de hechos y detalles comerciales, pero no pueden redactar disposiciones que requieran asesoría legal.']],
    ['forms-exception', 'state_rules', 'state', 0, 'TREC Rules, 22 TAC §537.11',
        ['A Texas license holder may use a contract form other than a TREC form when', ['the form was prepared by a Texas attorney and the owner requires it', 'the agent prefers it', 'the buyer\'s lender is out of state', 'the sale is under $100,000'], 'Exceptions include forms prepared by a Texas attorney and required by the owner, and forms required by a government agency.'],
        ['Un agente con licencia de Texas puede usar un formulario de contrato distinto de los de TREC cuando', ['lo preparó un abogado de Texas y el dueño lo exige', 'el agente lo prefiere', 'el prestamista del comprador es de otro estado', 'la venta es menor de $100,000'], 'Las excepciones incluyen formularios preparados por un abogado de Texas y exigidos por el dueño, y formularios exigidos por una agencia del gobierno.']],
    ['title-notice', 'state_rules', 'state', 1, 'Texas Occupations Code §1101.555',
        ['At or before closing, a Texas license holder must advise the buyer in writing to', ['buy a home warranty', 'have the abstract examined by an attorney or get a title insurance policy', 'hire an inspector', 'record the deed personally'], 'The law requires written advice to get an abstract examined or obtain an owner\'s title policy.'],
        ['En el cierre o antes, un agente con licencia de Texas debe aconsejar por escrito al comprador que', ['compre una garantía de vivienda', 'haga revisar el extracto de título por un abogado u obtenga una póliza de seguro de título', 'contrate a un inspector', 'inscriba él mismo la escritura'], 'La ley exige aconsejar por escrito que un abogado revise el extracto de título o que se obtenga una póliza de título del propietario.']],
    ['consumer-notice', 'state_rules', 'state', 2, 'TREC Rules, 22 TAC §531.18',
        ['Every Texas brokerage must make the TREC Consumer Protection Notice available', ['only when a consumer asks', 'only at closing', 'in each place of business and through a link on its website', 'only to sellers'], 'The notice explains how to file a complaint and the Recovery Trust Account; it must be displayed and linked online.'],
        ['Toda agencia de Texas debe poner a disposición el Aviso de Protección al Consumidor de TREC', ['solo cuando un consumidor lo pide', 'solo en el cierre', 'en cada lugar de negocio y mediante un enlace en su sitio web', 'solo a los vendedores'], 'El aviso explica cómo presentar una queja y la Cuenta Fiduciaria de Recuperación; debe exhibirse y tener un enlace en línea.']],
    ['iabs-when', 'state_rules', 'state', 3, 'Texas Occupations Code §1101.558',
        ['A Texas license holder must give the Information About Brokerage Services (IABS) notice', ['at closing', 'only to sellers', 'when the listing is signed', 'at the first substantive communication about specific real property'], 'The IABS goes out at the first substantive communication with a party about specific property.'],
        ['Un agente con licencia de Texas debe entregar el aviso de Información sobre Servicios de Corretaje (IABS)', ['en el cierre', 'solo a los vendedores', 'cuando se firma el listado', 'en la primera comunicación sustancial sobre una propiedad específica'], 'El IABS se entrega en la primera comunicación sustancial con una parte sobre una propiedad específica.']],
    ['iabs-exception-lease', 'state_rules', 'state', 0, 'Texas Occupations Code §1101.558',
        ['The IABS notice is NOT required when the transaction is', ['a residential lease of 1 year or less with no sale being considered', 'any commercial sale', 'a sale to a first-time buyer', 'a sale of land'], 'Residential leases of up to 1 year with no sale considered, and meetings with a party represented by another license holder, are exceptions.'],
        ['El aviso IABS NO es obligatorio cuando la operación es', ['un arrendamiento residencial de 1 año o menos sin considerar una venta', 'cualquier venta comercial', 'una venta a un comprador primerizo', 'una venta de terreno'], 'Los arrendamientos residenciales de hasta 1 año sin considerar una venta, y las reuniones con una parte representada por otro agente, son excepciones.']],
    ['iabs-represented', 'state_rules', 'state', 1, 'Texas Occupations Code §1101.558',
        ['A listing agent meets a buyer who already has a buyer\'s agent. The listing agent', ['must give the buyer the IABS anyway', 'does not have to give the buyer the IABS', 'must get TREC approval to talk to the buyer', 'must refuse to talk to the buyer'], 'The IABS isn\'t required when meeting a party who is represented by another license holder.'],
        ['El agente del listado se reúne con un comprador que ya tiene agente. El agente del listado', ['debe entregarle el IABS de todos modos', 'no tiene que entregarle el IABS', 'necesita aprobación de TREC para hablar con él', 'debe negarse a hablar con él'], 'El IABS no es obligatorio al reunirse con una parte que está representada por otro agente con licencia.']],
    ['iabs-not-contract', 'state_rules', 'state', 2, 'TREC Information About Brokerage Services form',
        ['The IABS notice', ['creates an agency relationship', 'obligates the consumer to use the broker', 'is informational and does not create a contract', 'replaces a listing agreement'], 'The IABS explains the types of representation and broker duties; it doesn\'t obligate anyone.'],
        ['El aviso IABS', ['crea una relación de agencia', 'obliga al consumidor a usar al bróker', 'es informativo y no crea un contrato', 'sustituye un contrato de listado'], 'El IABS explica los tipos de representación y los deberes del bróker; no obliga a nadie.']],
    ['iabs-website', 'state_rules', 'state', 3, 'TREC Rules, 22 TAC §535.155',
        ['A Texas brokerage website must show a link to the IABS labeled', ['"Agency Disclosure"', '"Privacy Policy"', '"Seller\'s Disclosure"', '"Texas Real Estate Commission Information About Brokerage Services"'], 'The link must use that label, in at least 10-point type, in a readily noticeable place on the home page.'],
        ['El sitio web de una agencia de Texas debe mostrar un enlace al IABS con el texto', ['"Agency Disclosure"', '"Privacy Policy"', '"Seller\'s Disclosure"', '"Texas Real Estate Commission Information About Brokerage Services"'], 'El enlace debe usar ese texto, con letra de al menos 10 puntos, en un lugar visible de la página principal.']],
    ['minimum-duties', 'state_rules', 'state', 0, 'Texas Occupations Code §1101.557',
        ['Under Texas law, a broker representing a party must at a minimum', ['inform the party of material information, answer questions and present offers', 'guarantee financing', 'perform the home inspection', 'pay the closing costs'], 'These minimum services apply even when a broker offers limited services.'],
        ['Según la ley de Texas, un bróker que representa a una parte debe como mínimo', ['informarle la información material, responder sus preguntas y presentar ofertas', 'garantizar el financiamiento', 'hacer la inspección de la casa', 'pagar los gastos de cierre'], 'Estos servicios mínimos aplican aunque el bróker ofrezca servicios limitados.']],
    ['no-dual-agency', 'state_rules', 'state', 1, 'Texas Occupations Code §1101.559',
        ['Texas law lets one broker work with both buyer and seller in the same deal only as', ['a dual agent', 'an intermediary, with both parties\' written consent', 'a subagent', 'a transaction coordinator'], 'Texas uses intermediary status, which requires written consent from both parties.'],
        ['La ley de Texas permite que un mismo bróker trabaje con el comprador y el vendedor en la misma operación solo como', ['agente dual', 'intermediario, con el consentimiento por escrito de ambas partes', 'subagente', 'coordinador de operaciones'], 'Texas usa la figura de intermediario, que requiere el consentimiento por escrito de ambas partes.']],
    ['intermediary-consent-content', 'state_rules', 'state', 2, 'Texas Occupations Code §1101.559',
        ['The written consent to intermediary status must state', ['the sales price', 'the inspection results', 'the source of any expected compensation to the broker', 'the buyer\'s maximum price'], 'The consent must say who will pay the broker.'],
        ['El consentimiento por escrito para actuar como intermediario debe indicar', ['el precio de venta', 'los resultados de la inspección', 'la fuente de la compensación que el bróker espera recibir', 'el precio máximo del comprador'], 'El consentimiento debe indicar quién le pagará al bróker.']],
    ['intermediary-nondisclose', 'state_rules', 'state', 3, 'Texas Occupations Code §1101.559',
        ['Without written instructions from the seller, an intermediary may not tell the buyer', ['the listed price', 'the property\'s square footage', 'known material defects', 'that the seller will accept less than the asking price'], 'An intermediary can\'t disclose either party\'s bargaining position or confidential information unless authorized in writing.'],
        ['Sin instrucciones por escrito del vendedor, el intermediario no puede decirle al comprador', ['el precio del listado', 'los pies cuadrados de la propiedad', 'los defectos materiales conocidos', 'que el vendedor aceptará menos que el precio pedido'], 'El intermediario no puede divulgar la posición de negociación de ninguna parte ni información confidencial sin autorización por escrito.']],
    ['intermediary-impartial', 'state_rules', 'state', 0, 'Texas Occupations Code §1101.559',
        ['A Texas intermediary must', ['treat all parties honestly and impartially', 'favor the party who pays more', 'favor the seller', 'favor the buyer'], 'An intermediary may not act so as to favor one party over the other.'],
        ['Un intermediario en Texas debe', ['tratar a todas las partes con honestidad e imparcialidad', 'favorecer a la parte que paga más', 'favorecer al vendedor', 'favorecer al comprador'], 'El intermediario no puede actuar de modo que favorezca a una parte sobre la otra.']],
    ['appointed-advice', 'state_rules', 'state', 1, 'Texas Occupations Code §1101.560',
        ['When an intermediary appoints one associate to the seller and another to the buyer, the appointed associates may', ['share each party\'s confidential information', 'give opinions and advice to the party each is appointed to', 'charge the parties separately', 'act as dual agents'], 'Appointed license holders may give opinions and advice during negotiations to the party they are appointed to.'],
        ['Cuando el intermediario nombra a un asociado para el vendedor y a otro para el comprador, los asociados nombrados pueden', ['compartir la información confidencial de cada parte', 'dar opiniones y consejos a la parte a la que fueron nombrados', 'cobrar a las partes por separado', 'actuar como agentes duales'], 'Los agentes nombrados pueden dar opiniones y consejos durante la negociación a la parte a la que fueron nombrados.']],
    ['intermediary-no-appointments', 'state_rules', 'state', 2, 'Texas Occupations Code §1101.559',
        ['If the intermediary broker does not make appointments, the broker and associates', ['may advise both parties freely', 'must withdraw from the transaction', 'may not give opinions or advice to either party', 'become dual agents'], 'Without appointments, the intermediary and associates stay neutral and give no opinions or advice.'],
        ['Si el bróker intermediario no hace nombramientos, el bróker y sus asociados', ['pueden asesorar libremente a ambas partes', 'deben retirarse de la operación', 'no pueden dar opiniones ni consejos a ninguna parte', 'se convierten en agentes duales'], 'Sin nombramientos, el intermediario y sus asociados se mantienen neutrales y no dan opiniones ni consejos.']],
    ['appointments-notice', 'state_rules', 'state', 3, 'Texas Occupations Code §1101.560',
        ['When a broker makes appointments as intermediary, the broker must', ['tell TREC within 10 days', 'get a new listing', 'charge an extra fee', 'notify each party in writing of the appointments'], 'Both parties receive written notice of who is appointed to each.'],
        ['Cuando el bróker hace nombramientos como intermediario, debe', ['avisar a TREC dentro de 10 días', 'obtener un nuevo listado', 'cobrar una tarifa adicional', 'notificar por escrito a cada parte los nombramientos'], 'Ambas partes reciben aviso por escrito de quién fue nombrado para cada una.']],
    ['trust-deposit', 'state_rules', 'state', 0, 'TREC Rules, 22 TAC §535.159',
        ['A Texas broker who receives earnest money must deposit it no later than', ['the close of business on the second business day after the contract is executed', 'the day of closing', 'within 10 days', 'whenever the seller asks'], 'Trust money goes into the trust account, or to the escrow agent, by the close of business on the second business day.'],
        ['Un bróker de Texas que recibe dinero de garantía debe depositarlo a más tardar', ['al cierre de operaciones del segundo día hábil después de firmarse el contrato', 'el día del cierre', 'dentro de 10 días', 'cuando el vendedor lo pida'], 'El dinero en fideicomiso va a la cuenta fiduciaria, o al agente de depósito, a más tardar al cierre del segundo día hábil.']],
    ['commingling', 'state_rules', 'state', 1, 'Texas Occupations Code §1101.652',
        ['Putting a client\'s earnest money into the broker\'s personal account is', ['conversion only if the money is spent', 'commingling, a violation', 'allowed for 30 days', 'allowed with a receipt'], 'Mixing trust money with the broker\'s own money is commingling and grounds for discipline.'],
        ['Depositar el dinero de garantía de un cliente en la cuenta personal del bróker es', ['apropiación indebida solo si se gasta', 'mezcla de fondos (commingling), una infracción', 'permitido por 30 días', 'permitido con un recibo'], 'Mezclar el dinero en fideicomiso con el dinero propio del bróker es commingling y es causa de sanción.']],
    ['ad-broker-name', 'state_rules', 'state', 2, 'TREC Rules, 22 TAC §535.155',
        ['In Texas advertising, the broker\'s name must appear', ['only on the website', 'smaller than the agent\'s name', 'in at least half the size of the largest contact information in the ad', 'only if the broker pays for the ad'], 'Every ad shows the broker\'s licensed or registered name in at least half the size of the largest contact information.'],
        ['En la publicidad en Texas, el nombre del bróker debe aparecer', ['solo en el sitio web', 'más pequeño que el nombre del agente', 'en al menos la mitad del tamaño de la información de contacto más grande del anuncio', 'solo si el bróker paga el anuncio'], 'Todo anuncio muestra el nombre con licencia o registrado del bróker en al menos la mitad del tamaño de la información de contacto más grande.']],
    ['team-name', 'state_rules', 'state', 3, 'TREC Rules, 22 TAC §535.155 (Advertisements)',
        ['A Texas team name must', ['end with "Realty"', 'be approved by the local association', 'include the agent\'s license number', 'include "team" or "group"'], 'Team names must include "team" or "group" so they aren\'t mistaken for a brokerage.'],
        ['El nombre de un equipo en Texas debe', ['terminar en "Realty"', 'ser aprobado por la asociación local', 'incluir el número de licencia del agente', 'incluir "team" o "group" (equipo o grupo)'], 'Los nombres de equipo deben incluir "team" o "group" para no confundirse con una agencia.']],
    ['misleading-ad', 'state_rules', 'state', 0, 'Texas Occupations Code §1101.652; TREC Rules, 22 TAC §535.155',
        ['An agent advertises a listing as "lake view" when the lake is visible only from the roof. This is', ['misleading advertising, a violation', 'puffing and always allowed', 'fine if the seller approved', 'required by the listing'], 'Ads must not be misleading or deceptive about the property.'],
        ['Un agente anuncia un listado con "vista al lago" cuando el lago solo se ve desde el techo. Esto es', ['publicidad engañosa, una infracción', 'exageración publicitaria y siempre permitida', 'aceptable si el vendedor lo aprobó', 'obligatorio según el listado'], 'Los anuncios no deben ser engañosos sobre la propiedad.']],
    ['effective-date', 'state_rules', 'state', 1, 'TREC One to Four Family Residential Contract (Resale)',
        ['The effective date of a Texas resale contract is', ['the date the buyer signs', 'the date of final acceptance, filled in by the broker', 'the date of closing', 'the date earnest money is delivered'], 'The broker fills in the date the last party accepted; all deadlines run from it.'],
        ['La fecha de vigencia de un contrato de reventa de Texas es', ['la fecha en que firma el comprador', 'la fecha de aceptación final, que llena el bróker', 'la fecha de cierre', 'la fecha en que se entrega el dinero de garantía'], 'El bróker anota la fecha en que la última parte aceptó; todos los plazos corren desde ella.']],
    ['earnest-delivery', 'state_rules', 'state', 2, 'TREC One to Four Family Residential Contract (Resale)',
        ['Under the current TREC resale contract, the buyer must deliver earnest money and the option fee to the escrow agent within', ['24 hours', '10 days', '3 days after the effective date', '7 days after the effective date'], 'Both payments are due to the escrow agent within 3 days after the effective date.'],
        ['Según el contrato de reventa actual de TREC, el comprador debe entregar el dinero de garantía y la tarifa de opción al agente de depósito dentro de', ['24 horas', '10 días', '3 días después de la fecha de vigencia', '7 días después de la fecha de vigencia'], 'Ambos pagos se entregan al agente de depósito dentro de 3 días después de la fecha de vigencia.']],
    ['option-deadline', 'state_rules', 'state', 3, 'TREC One to Four Family Residential Contract (Resale), Paragraph 5',
        ['To end the contract during the option period, the buyer\'s notice must be given by', ['midnight on the last day', 'noon on the last day', 'the closing date', '5:00 p.m. local time where the property is, on the last day'], 'Time is of the essence for the option period: notice must be given by 5:00 p.m. local time on the last day.'],
        ['Para terminar el contrato durante el periodo de opción, el aviso del comprador debe darse a más tardar', ['a la medianoche del último día', 'al mediodía del último día', 'en la fecha de cierre', 'a las 5:00 p. m., hora local de la propiedad, del último día'], 'El tiempo es esencial en el periodo de opción: el aviso debe darse a más tardar a las 5:00 p. m., hora local, del último día.']],
    ['option-fee-goes', 'state_rules', 'state', 0, 'TREC One to Four Family Residential Contract (Resale), Paragraph 5',
        ['If the buyer terminates during the option period, the option fee', ['is not refunded to the buyer', 'is refunded to the buyer', 'goes to the listing broker', 'is split between the brokers'], 'The option fee pays for the right to terminate; the buyer gets the earnest money back but not the option fee.'],
        ['Si el comprador termina durante el periodo de opción, la tarifa de opción', ['no se le devuelve al comprador', 'se le devuelve al comprador', 'va al bróker del listado', 'se divide entre los brókeres'], 'La tarifa de opción paga el derecho a terminar; el comprador recupera el dinero de garantía, pero no la tarifa de opción.']],
    ['option-fee-credit', 'state_rules', 'state', 1, 'TREC One to Four Family Residential Contract (Resale), Paragraph 5',
        ['If the sale closes, the option fee', ['goes back to the buyer separately', 'is credited to the buyer at closing', 'is paid to the title company', 'is forfeited to the seller with no credit'], 'The option fee will be credited to the sales price at closing.'],
        ['Si la venta se cierra, la tarifa de opción', ['se devuelve aparte al comprador', 'se acredita al comprador en el cierre', 'se paga a la compañía de títulos', 'se la queda el vendedor sin crédito'], 'La tarifa de opción se acredita al precio de venta en el cierre.']],
    ['no-option-fee', 'state_rules', 'state', 2, 'TREC One to Four Family Residential Contract (Resale), Paragraph 5',
        ['If the buyer fails to pay the option fee on time, the buyer', ['may still terminate for any reason', 'loses the earnest money', 'has no unrestricted right to terminate', 'must close within 3 days'], 'Without timely payment of the option fee, the buyer doesn\'t get the termination option.'],
        ['Si el comprador no paga a tiempo la tarifa de opción, el comprador', ['aún puede terminar por cualquier motivo', 'pierde el dinero de garantía', 'no tiene el derecho ilimitado a terminar', 'debe cerrar dentro de 3 días'], 'Sin el pago puntual de la tarifa de opción, el comprador no obtiene la opción de terminar.']],
    ['third-party-financing', 'state_rules', 'state', 3, 'TREC Third Party Financing Addendum',
        ['Under the Third Party Financing Addendum, if the buyer can\'t get buyer approval within the stated days and gives timely notice, the buyer', ['loses the earnest money', 'must close anyway', 'must find another lender', 'may terminate and receive the earnest money back'], 'Timely notice under the buyer approval period lets the buyer terminate with the earnest money refunded.'],
        ['Según el Anexo de Financiamiento de Terceros, si el comprador no obtiene la aprobación en los días indicados y avisa a tiempo, el comprador', ['pierde el dinero de garantía', 'debe cerrar de todos modos', 'debe buscar otro prestamista', 'puede terminar y recuperar el dinero de garantía'], 'El aviso oportuno durante el periodo de aprobación permite al comprador terminar con devolución del dinero de garantía.']],
    ['seller-default', 'state_rules', 'state', 0, 'TREC One to Four Family Residential Contract (Resale), Paragraph 15',
        ['If the seller defaults under the TREC resale contract, the buyer may', ['enforce specific performance or terminate and get the earnest money back', 'only sue for damages', 'keep the property without paying', 'take the seller\'s commission'], 'The buyer may seek specific performance or other relief, or terminate and receive the earnest money.'],
        ['Si el vendedor incumple el contrato de reventa de TREC, el comprador puede', ['exigir el cumplimiento forzoso o terminar y recuperar el dinero de garantía', 'solo demandar daños', 'quedarse con la propiedad sin pagar', 'tomar la comisión del vendedor'], 'El comprador puede pedir el cumplimiento forzoso u otro recurso, o terminar y recibir el dinero de garantía.']],
    ['buyer-default', 'state_rules', 'state', 1, 'TREC One to Four Family Residential Contract (Resale), Paragraph 15',
        ['If the buyer defaults under the TREC resale contract, the seller may', ['have the buyer arrested', 'enforce specific performance or terminate and keep the earnest money', 'keep the option fee and the property taxes', 'sue the buyer\'s agent'], 'The seller may enforce specific performance or other relief, or terminate and receive the earnest money as liquidated damages.'],
        ['Si el comprador incumple el contrato de reventa de TREC, el vendedor puede', ['hacer arrestar al comprador', 'exigir el cumplimiento forzoso o terminar y quedarse con el dinero de garantía', 'quedarse con la tarifa de opción y los impuestos', 'demandar al agente del comprador'], 'El vendedor puede exigir el cumplimiento forzoso u otro recurso, o terminar y recibir el dinero de garantía como daños liquidados.']],
    ['title-policy-seller', 'state_rules', 'state', 2, 'TREC One to Four Family Residential Contract (Resale), Paragraph 6',
        ['Under the TREC resale contract, the owner\'s title policy is', ['always paid by the buyer', 'paid by the lender', 'paid by whichever party the contract names, usually the seller', 'not needed in Texas'], 'The contract lets the parties choose; the seller usually furnishes the owner\'s policy.'],
        ['Según el contrato de reventa de TREC, la póliza de título del propietario', ['siempre la paga el comprador', 'la paga el prestamista', 'la paga la parte que indique el contrato, normalmente el vendedor', 'no se necesita en Texas'], 'El contrato permite que las partes elijan; normalmente el vendedor proporciona la póliza del propietario.']],
    ['backup-addendum', 'state_rules', 'state', 3, 'TREC Addendum for Back-Up Contract',
        ['A buyer signs a contract on a home already under contract with another buyer. The parties should use', ['an amendment', 'a seller financing addendum', 'a new listing', 'the Addendum for Back-Up Contract'], 'The back-up addendum makes the contract depend on the first contract ending.'],
        ['Un comprador firma un contrato por una casa que ya está bajo contrato con otro comprador. Las partes deben usar', ['una enmienda', 'el anexo de financiamiento del vendedor', 'un nuevo listado', 'el Anexo para Contrato de Respaldo'], 'El anexo de respaldo hace que el contrato dependa de que termine el primer contrato.']],
    ['hoa-addendum', 'state_rules', 'state', 0, 'TREC Addendum for Property Subject to Mandatory Membership in a Property Owners Association',
        ['A home is in a mandatory homeowners association. Which TREC form goes with the contract?', ['The addendum for property subject to mandatory membership in a property owners association', 'The seller financing addendum', 'The back-up contract addendum', 'The lead-based paint addendum'], 'The POA addendum covers delivery of the subdivision information and the buyer\'s right to terminate.'],
        ['Una casa está en una asociación de propietarios obligatoria. ¿Qué formulario de TREC acompaña al contrato?', ['El anexo para propiedad sujeta a membresía obligatoria en una asociación de propietarios', 'El anexo de financiamiento del vendedor', 'El anexo para contrato de respaldo', 'El anexo de pintura con plomo'], 'El anexo de la asociación cubre la entrega de la información de la subdivisión y el derecho del comprador a terminar.']],
    ['amendment-form', 'state_rules', 'state', 1, 'TREC Amendment to Contract',
        ['After the contract is signed, the parties agree the seller will make repairs. They should use', ['a new contract', 'the TREC Amendment to Contract', 'the IABS', 'a notice of termination'], 'The amendment form records agreed changes, such as repairs, price or dates.'],
        ['Después de firmar el contrato, las partes acuerdan que el vendedor hará reparaciones. Deben usar', ['un contrato nuevo', 'la Enmienda al Contrato de TREC', 'el IABS', 'un aviso de terminación'], 'El formulario de enmienda registra los cambios acordados, como reparaciones, precio o fechas.']],
    ['unimproved-form', 'state_rules', 'state', 2, 'TREC Unimproved Property Contract',
        ['To buy a vacant residential lot, a Texas agent normally uses the TREC', ['resale contract', 'farm and ranch contract only', 'unimproved property contract', 'condominium contract'], 'Each TREC contract fits a kind of property; vacant land uses the unimproved property contract.'],
        ['Para comprar un lote residencial vacío, un agente de Texas normalmente usa el contrato de TREC de', ['reventa', 'solo granja y rancho', 'propiedad sin mejoras', 'condominio'], 'Cada contrato de TREC corresponde a un tipo de propiedad; el terreno vacío usa el contrato de propiedad sin mejoras.']],
    ['sellers-disclosure-late', 'state_rules', 'state', 3, 'Texas Property Code §5.008',
        ['If the seller delivers the required seller\'s disclosure after the contract is signed, the buyer may terminate for any reason within', ['3 days', '10 days', '30 days', '7 days after receiving it'], 'Late delivery gives the buyer 7 days to terminate, with the earnest money returned.'],
        ['Si el vendedor entrega la divulgación del vendedor obligatoria después de firmar el contrato, el comprador puede terminar por cualquier motivo dentro de', ['3 días', '10 días', '30 días', '7 días después de recibirla'], 'La entrega tardía da al comprador 7 días para terminar, con devolución del dinero de garantía.']],
    ['sellers-disclosure-exempt', 'state_rules', 'state', 0, 'Texas Property Code §5.008',
        ['Which seller is NOT required to give the Texas seller\'s disclosure notice?', ['A lender selling a home it acquired by foreclosure', 'An owner selling a home lived in for 10 years', 'An owner who rented the home out', 'An owner selling with an agent'], 'Exemptions include foreclosure transfers, court-ordered sales, sales between co-owners or to a spouse, and new homes never occupied.'],
        ['¿Qué vendedor NO está obligado a dar el aviso de divulgación del vendedor de Texas?', ['Un prestamista que vende una casa que obtuvo por ejecución hipotecaria', 'Un dueño que vende la casa donde vivió 10 años', 'Un dueño que rentó la casa', 'Un dueño que vende con un agente'], 'Las exenciones incluyen transferencias por ejecución, ventas ordenadas por un tribunal, ventas entre copropietarios o al cónyuge, y casas nuevas nunca ocupadas.']],
    ['lead-paint', 'state_rules', 'state', 1, '42 U.S.C. §4852d; TREC Addendum for Seller\'s Disclosure of Information on Lead-Based Paint',
        ['For a Texas home built before 1978, the seller must give the buyer', ['a radon test', 'the lead-based paint disclosure and the EPA pamphlet', 'an asbestos test', 'a termite report'], 'Federal law requires the lead disclosure, the pamphlet and the chance to have a lead inspection for homes built before 1978.'],
        ['En una casa de Texas construida antes de 1978, el vendedor debe dar al comprador', ['una prueba de radón', 'la divulgación de pintura con plomo y el folleto de la EPA', 'una prueba de asbesto', 'un informe de termitas'], 'La ley federal exige la divulgación de plomo, el folleto y la oportunidad de hacer una inspección de plomo en casas construidas antes de 1978.']],
    ['mud-notice', 'state_rules', 'state', 2, 'Texas Water Code §49.452',
        ['A home is in a municipal utility district (MUD). Before the contract is signed, the seller must give the buyer', ['a flood certificate', 'a survey', 'the statutory notice about the district\'s taxes and bonds', 'nothing; MUDs are public'], 'The MUD notice tells the buyer about the district\'s tax rate and bonded debt.'],
        ['Una casa está en un distrito municipal de servicios (MUD). Antes de firmar el contrato, el vendedor debe darle al comprador', ['un certificado de inundación', 'un levantamiento', 'el aviso legal sobre los impuestos y bonos del distrito', 'nada; los MUD son públicos'], 'El aviso del MUD informa al comprador sobre la tasa de impuesto y la deuda en bonos del distrito.']],
    ['coastal-notice', 'state_rules', 'state', 3, 'Texas Natural Resources Code §33.135',
        ['A contract for property seaward of the Gulf Intracoastal Waterway must include', ['a lead-based paint addendum', 'a MUD notice', 'an HOA addendum', 'a notice about coastal area property'], 'Texas requires a coastal area notice for property seaward of the Gulf Intracoastal Waterway.'],
        ['Un contrato por una propiedad hacia el mar desde el Canal Intracostero del Golfo debe incluir', ['un anexo de pintura con plomo', 'un aviso de MUD', 'un anexo de la asociación de propietarios', 'un aviso sobre propiedad en zona costera'], 'Texas exige un aviso de zona costera para propiedades hacia el mar desde el Canal Intracostero del Golfo.']],
    ['annexation-notice', 'state_rules', 'state', 0, 'Texas Property Code §5.011',
        ['A seller of property in a city\'s extraterritorial jurisdiction (ETJ) must notify the buyer', ['that the property may later be annexed by the city', 'of the property\'s school ratings', 'of the city\'s crime rate', 'of nothing'], 'Property in an ETJ requires a notice that it may be annexed.'],
        ['El vendedor de una propiedad en la jurisdicción extraterritorial (ETJ) de una ciudad debe avisar al comprador', ['que la ciudad podría anexar la propiedad más adelante', 'las calificaciones de las escuelas', 'el índice de delitos de la ciudad', 'nada'], 'Una propiedad en una ETJ requiere un aviso de que podría ser anexada.']],
    ['homestead-urban', 'state_rules', 'state', 1, 'Texas Property Code §41.002',
        ['A Texas urban homestead is protected up to', ['1 acre', '10 acres', '100 acres', '200 acres'], 'An urban homestead can be up to 10 acres in one or more contiguous lots.'],
        ['En Texas, la vivienda familiar (homestead) urbana está protegida hasta', ['1 acre', '10 acres', '100 acres', '200 acres'], 'La vivienda familiar urbana puede tener hasta 10 acres en uno o más lotes contiguos.']],
    ['homestead-rural', 'state_rules', 'state', 2, 'Texas Property Code §41.002',
        ['A rural homestead for a family in Texas is protected up to', ['10 acres', '100 acres', '200 acres', '640 acres'], 'A family\'s rural homestead can be up to 200 acres; a single adult\'s, 100 acres.'],
        ['En Texas, la vivienda familiar rural de una familia está protegida hasta', ['10 acres', '100 acres', '200 acres', '640 acres'], 'La vivienda familiar rural de una familia puede tener hasta 200 acres; la de un adulto soltero, 100 acres.']],
    ['homestead-forced-sale', 'state_rules', 'state', 3, 'Texas Constitution, Art. XVI, §50',
        ['A Texas homestead can be forced into sale for', ['credit card debt', 'a medical bill', 'a personal loan judgment', 'unpaid property taxes on it'], 'Homesteads are protected from most creditors; exceptions include purchase money, property taxes, home equity and improvement loans.'],
        ['En Texas, una vivienda familiar puede venderse a la fuerza por', ['deudas de tarjetas de crédito', 'una factura médica', 'una sentencia por un préstamo personal', 'impuestos impagos sobre ella'], 'La vivienda familiar está protegida de la mayoría de los acreedores; las excepciones incluyen el precio de compra, los impuestos, el préstamo sobre el capital y las mejoras.']],
    ['home-equity-ltv', 'state_rules', 'state', 0, 'Texas Constitution, Art. XVI, §50(a)(6)',
        ['A Texas home equity loan, combined with other debt on the homestead, can\'t exceed what share of fair market value?', ['80%', '90%', '95%', '100%'], 'Texas caps total debt on a homestead with a home equity loan at 80% of fair market value.'],
        ['Un préstamo sobre el capital de la vivienda en Texas, junto con otras deudas sobre la vivienda familiar, no puede superar qué porcentaje del valor de mercado?', ['80%', '90%', '95%', '100%'], 'Texas limita la deuda total sobre una vivienda familiar con préstamo sobre el capital al 80% del valor de mercado.']],
    ['home-equity-wait', 'state_rules', 'state', 1, 'Texas Constitution, Art. XVI, §50(a)(6)',
        ['A Texas home equity loan can\'t close until at least how many days after the borrower receives the required notice?', ['3', '12', '30', '7'], 'The 12-day notice gives the borrower time to consider the loan; the borrower can also rescind within 3 days after closing.'],
        ['Un préstamo sobre el capital de la vivienda en Texas no puede cerrarse hasta que pasen al menos cuántos días después de que el prestatario recibe el aviso obligatorio?', ['3', '12', '30', '7'], 'El aviso de 12 días da tiempo para considerar el préstamo; el prestatario también puede rescindir dentro de 3 días después del cierre.']],
    ['community-property', 'state_rules', 'state', 2, 'Texas Family Code §3.003',
        ['Property a Texas couple buys during their marriage is presumed to be', ['the husband\'s separate property', 'held in tenancy in common', 'community property', 'the wife\'s separate property'], 'Texas is a community property state; property acquired during marriage is presumed community.'],
        ['La propiedad que una pareja de Texas compra durante su matrimonio se presume que es', ['propiedad separada del esposo', 'copropiedad en común', 'propiedad comunitaria (bienes gananciales)', 'propiedad separada de la esposa'], 'Texas es un estado de propiedad comunitaria; lo adquirido durante el matrimonio se presume comunitario.']],
    ['separate-property', 'state_rules', 'state', 3, 'Texas Family Code §3.001',
        ['Which is separate property of a married Texan?', ['A paycheck earned during the marriage', 'A home bought jointly last year', 'A car bought with marital savings', 'A house inherited during the marriage'], 'Property owned before marriage or received by gift or inheritance is separate property.'],
        ['¿Cuál es propiedad separada de un texano casado?', ['Un sueldo ganado durante el matrimonio', 'Una casa comprada en conjunto el año pasado', 'Un auto comprado con ahorros del matrimonio', 'Una casa heredada durante el matrimonio'], 'Lo que se tenía antes del matrimonio o se recibió por regalo o herencia es propiedad separada.']],
    ['homestead-spouse', 'state_rules', 'state', 0, 'Texas Family Code §5.001',
        ['A married Texan wants to sell the family homestead, which is the seller\'s separate property. The other spouse', ['must join in signing the deed', 'has no say', 'must only be told after closing', 'must buy it first'], 'Both spouses must join in selling or encumbering the homestead, whoever owns it.'],
        ['Un texano casado quiere vender la vivienda familiar, que es su propiedad separada. El otro cónyuge', ['debe firmar también la escritura', 'no tiene nada que decir', 'solo debe ser informado después del cierre', 'debe comprarla primero'], 'Ambos cónyuges deben participar para vender o gravar la vivienda familiar, sea quien sea el dueño.']],
    ['foreclosure-day', 'state_rules', 'state', 1, 'Texas Property Code §51.002',
        ['Nonjudicial foreclosure sales in Texas are held', ['any business day', 'on the first Tuesday of the month', 'on the last Friday of the month', 'only in January'], 'Sales are held on the first Tuesday of the month, between 10 a.m. and 4 p.m., at the county\'s designated place.'],
        ['En Texas, las ventas por ejecución hipotecaria extrajudicial se hacen', ['cualquier día hábil', 'el primer martes del mes', 'el último viernes del mes', 'solo en enero'], 'Las ventas se hacen el primer martes del mes, entre las 10 a. m. y las 4 p. m., en el lugar designado por el condado.']],
    ['foreclosure-notice', 'state_rules', 'state', 2, 'Texas Property Code §51.002',
        ['Notice of a Texas nonjudicial foreclosure sale must be given at least how many days before the sale?', ['7', '10', '21', '90'], 'The notice of sale must be posted, filed and mailed at least 21 days before the sale.'],
        ['¿Con cuántos días de anticipación como mínimo se debe dar el aviso de una venta por ejecución extrajudicial en Texas?', ['7', '10', '21', '90'], 'El aviso de venta debe publicarse, presentarse y enviarse por correo al menos 21 días antes de la venta.']],
    ['foreclosure-cure', 'state_rules', 'state', 3, 'Texas Property Code §51.002(d)',
        ['Before posting a residence for foreclosure in Texas, the lender must give the borrower notice of default and at least how many days to cure?', ['5', '10', '30', '20'], 'For a residence, the borrower gets at least 20 days to cure the default before the notice of sale.'],
        ['Antes de anunciar la ejecución de una residencia en Texas, el prestamista debe dar al prestatario aviso de incumplimiento y al menos cuántos días para corregirlo?', ['5', '10', '30', '20'], 'En una residencia, el prestatario tiene al menos 20 días para corregir el incumplimiento antes del aviso de venta.']],
    ['adverse-3', 'state_rules', 'state', 0, 'Texas Civil Practice and Remedies Code §16.024',
        ['The shortest adverse possession period in Texas, for a possessor holding under title or color of title, is', ['3 years', '5 years', '10 years', '25 years'], 'Texas has 3-, 5-, 10- and 25-year periods; the 3-year period requires title or color of title.'],
        ['El plazo más corto de posesión adversa en Texas, para quien posee con título o apariencia de título, es de', ['3 años', '5 años', '10 años', '25 años'], 'Texas tiene plazos de 3, 5, 10 y 25 años; el de 3 años requiere título o apariencia de título.']],
    ['groundwater', 'state_rules', 'state', 1, 'Texas Water Code Chapter 36',
        ['Texas groundwater is generally governed by', ['riparian rights', 'the rule of capture, subject to groundwater districts', 'prior appropriation permits', 'federal ownership'], 'Landowners own the groundwater beneath their land under the rule of capture, as limited by groundwater conservation districts.'],
        ['En Texas, el agua subterránea en general se rige por', ['los derechos ribereños', 'la regla de captura, sujeta a los distritos de aguas subterráneas', 'los permisos de apropiación previa', 'la propiedad federal'], 'Los dueños son propietarios del agua subterránea bajo su terreno según la regla de captura, limitada por los distritos de conservación.']],
    ['surface-water', 'state_rules', 'state', 2, 'Texas Water Code §11.021',
        ['Surface water in Texas rivers and streams belongs to', ['the adjoining landowner', 'the county', 'the state, and use is allocated by permit', 'the nearest city'], 'Texas surface water is state water, allocated under the prior appropriation system.'],
        ['El agua superficial de ríos y arroyos de Texas pertenece a', ['el dueño colindante', 'el condado', 'el estado, y su uso se asigna por permiso', 'la ciudad más cercana'], 'El agua superficial de Texas es del estado y se asigna con el sistema de apropiación previa.']],
    ['mineral-dominant', 'state_rules', 'state', 3, 'Texas common law (accommodation doctrine)',
        ['In Texas, when the mineral estate is severed from the surface, the mineral estate is', ['servient to the surface', 'void', 'owned by the state', 'dominant, with reasonable use of the surface'], 'The mineral owner may reasonably use the surface to develop minerals, subject to the accommodation doctrine.'],
        ['En Texas, cuando los minerales se separan de la superficie, el derecho sobre los minerales es', ['sirviente de la superficie', 'nulo', 'propiedad del estado', 'dominante, con uso razonable de la superficie'], 'El dueño de los minerales puede usar razonablemente la superficie para explotarlos, sujeto a la doctrina de acomodo.']],
    ['deposit-refund', 'state_rules', 'state', 0, 'Texas Property Code §92.103',
        ['A Texas residential landlord must refund the security deposit, or give a written list of deductions, within how many days after the tenant moves out?', ['30', '14', '45', '60'], 'The landlord has 30 days after the tenant surrenders the premises.'],
        ['¿En cuántos días después de que el inquilino desocupa debe un arrendador residencial de Texas devolver el depósito de seguridad o dar una lista escrita de deducciones?', ['30', '14', '45', '60'], 'El arrendador tiene 30 días después de que el inquilino entrega el inmueble.']],
    ['appraisal-date', 'state_rules', 'state', 1, 'Texas Tax Code §23.01',
        ['Texas appraisal districts value property for taxes as of', ['July 1', 'January 1', 'the date of sale', 'October 1'], 'Property is appraised at its market value as of January 1.'],
        ['Los distritos de avalúo de Texas valoran la propiedad para impuestos a la fecha del', ['1 de julio', '1 de enero', 'día de la venta', '1 de octubre'], 'La propiedad se valúa a su valor de mercado al 1 de enero.']],
    ['tax-delinquent', 'state_rules', 'state', 2, 'Texas Tax Code §31.02',
        ['Texas property taxes not paid by what date become delinquent?', ['December 31', 'April 15', 'January 31', 'June 30'], 'Taxes are generally due on receipt of the bill and become delinquent if not paid by January 31.'],
        ['¿Después de qué fecha se vuelven morosos los impuestos sobre la propiedad de Texas no pagados?', ['31 de diciembre', '15 de abril', '31 de enero', '30 de junio'], 'Los impuestos en general vencen al recibir la factura y quedan morosos si no se pagan a más tardar el 31 de enero.']],
    ['homestead-cap', 'state_rules', 'state', 3, 'Texas Tax Code §23.23',
        ['For a residence homestead, the appraised value for taxes generally can\'t rise more than what share per year?', ['5%', '20%', '3%', '10%'], 'The homestead cap limits appraised value increases to 10% a year (plus new improvements).'],
        ['En una vivienda familiar, el valor tasado para impuestos en general no puede subir más de qué porcentaje al año?', ['5%', '20%', '3%', '10%'], 'El límite de la vivienda familiar restringe los aumentos del valor tasado al 10% anual (más las mejoras nuevas).']],
    ['fair-housing-texas', 'state_rules', 'state', 0, 'Texas Property Code Chapter 301 (Texas Fair Housing Act)',
        ['The Texas Fair Housing Act is enforced by', ['the Texas Workforce Commission Civil Rights Division', 'TREC alone', 'the county clerk', 'the local association of REALTORS®'], 'Complaints under the Texas Fair Housing Act go to the TWC Civil Rights Division, as well as HUD.'],
        ['La Ley de Vivienda Justa de Texas la hace cumplir', ['la División de Derechos Civiles de la Comisión de la Fuerza Laboral de Texas', 'solo TREC', 'el secretario del condado', 'la asociación local de REALTORS®'], 'Las quejas según la Ley de Vivienda Justa de Texas van a la División de Derechos Civiles de la TWC, y también a HUD.']],
    ['executory-record', 'state_rules', 'state', 1, 'Texas Property Code §5.076',
        ['A Texas seller under an executory contract for a residence (contract for deed) must record the contract within', ['3 days', '30 days after signing', '1 year', 'no time limit'], 'The seller records the executory contract within 30 days, and sends the buyer an annual accounting statement.'],
        ['En Texas, el vendedor con un contrato de venta a plazos (contract for deed) de una residencia debe inscribir el contrato dentro de', ['3 días', '30 días después de firmarlo', '1 año', 'ningún plazo'], 'El vendedor inscribe el contrato de venta a plazos dentro de 30 días y envía al comprador un estado de cuenta anual.']],
    ['homestead-mechanics-lien', 'state_rules', 'state', 2, 'Texas Property Code §53.254',
        ['To get a valid mechanic\'s lien for work on a Texas homestead, the contractor needs', ['an oral agreement', 'a building permit only', 'a written contract signed by the owner and spouse before work begins', 'nothing extra'], 'Homestead liens require a written contract, signed by both spouses, made before the work starts.'],
        ['Para tener un gravamen de constructor válido por trabajos en una vivienda familiar de Texas, el contratista necesita', ['un acuerdo verbal', 'solo un permiso de construcción', 'un contrato por escrito firmado por el dueño y su cónyuge antes de empezar el trabajo', 'nada adicional'], 'Los gravámenes sobre la vivienda familiar requieren un contrato escrito, firmado por ambos cónyuges, antes de empezar el trabajo.']],
    ['dtpa', 'state_rules', 'state', 3, 'Texas Business and Commerce Code §17.46 (Deceptive Trade Practices Act)',
        ['A Texas consumer harmed by an agent\'s false statement of fact about a home may sue under', ['the Texas Tax Code', 'the Recovery Trust Account only', 'the Texas Family Code', 'the Deceptive Trade Practices Act (DTPA)'], 'The DTPA covers false, misleading or deceptive acts; the professional services exemption doesn\'t cover misrepresenting facts.'],
        ['Un consumidor de Texas perjudicado por una afirmación falsa de un agente sobre una casa puede demandar según', ['el Código Fiscal de Texas', 'solo la Cuenta Fiduciaria de Recuperación', 'el Código de Familia de Texas', 'la Ley de Prácticas Comerciales Engañosas (DTPA)'], 'La DTPA cubre actos falsos, engañosos o fraudulentos; la exención de servicios profesionales no cubre tergiversar hechos.']],
];
